CREATE DATABASE reading_club
 CHARACTER SET utf8mb4
 COLLATE utf8mb4_0900_bin;

USE club_a;
SELECT id, name FROM tags;
-- 第二条语句解析为club_a中的tags，不移动其他库的数据。

ALTER DATABASE reading_club
 CHARACTER SET utf8mb4
 COLLATE utf8mb4_0900_bin;

SHOW ENGINES;
-- 关注Engine、Support、Transactions、XA、Savepoints等列。
-- Support标注DEFAULT的引擎是当前默认选择。

START TRANSACTION;
UPDATE students SET score = score + 5 WHERE score >= 70;
ROLLBACK;
SELECT id, score FROM students ORDER BY id;

前提：legacy_counts是一张原生MyISAM表。
START TRANSACTION;
UPDATE legacy_counts SET total = total + 1 WHERE id = 1;
ROLLBACK;
